const nav=document.querySelector('.nav');const burger=document.querySelector('.burger');addEventListener('scroll',()=>nav.classList.toggle('is-scrolled',scrollY>60),{passive:true});burger.addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');burger.setAttribute('aria-expanded',String(open));burger.setAttribute('aria-label',open?'Fechar menu':'Abrir menu')});document.querySelectorAll('.sheet a').forEach(a=>a.addEventListener('click',()=>{document.body.classList.remove('nav-open');burger.setAttribute('aria-expanded','false')}));